arduino.setup:
#define RAIN_AO_PIN ${AO}
#define RAIN_DO_PIN ${DO}
pinMode(RAIN_DO_PIN, INPUT);
Serial.println("Raindrop Module ready.");

arduino.loop:
int rainLevel = analogRead(RAIN_AO_PIN);
int doVal = digitalRead(RAIN_DO_PIN);
Serial.print("Rain Level (AO): ");
Serial.print(rainLevel);
Serial.print("  DO: ");
Serial.println(doVal == LOW ? "RAIN DETECTED" : "Dry");
delay(1000);
